#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <unistd.h>

ssize_t readlink(const char *path, char *buf, size_t bufsiz) {
  static ssize_t (*real_readlink)(const char *, char *, size_t) = NULL;
  if (!real_readlink) real_readlink = dlsym(RTLD_NEXT, "readlink");
  ssize_t result = real_readlink(path, buf, bufsiz);
  int saved = errno;
  fprintf(stderr, "TRACE readlink(%s,%zu)=%zd errno=%d", path, bufsiz, result, saved);
  if (result > 0) fprintf(stderr, " target=%.*s", (int)result, buf);
  fputc('\n', stderr);
  errno = saved;
  return result;
}

ssize_t readlinkat(int dirfd, const char *path, char *buf, size_t bufsiz) {
  static ssize_t (*real_readlinkat)(int, const char *, char *, size_t) = NULL;
  if (!real_readlinkat) real_readlinkat = dlsym(RTLD_NEXT, "readlinkat");
  ssize_t result = real_readlinkat(dirfd, path, buf, bufsiz);
  int saved = errno;
  fprintf(stderr, "TRACE readlinkat(%d,%s,%zu)=%zd errno=%d\n", dirfd, path, bufsiz, result, saved);
  errno = saved;
  return result;
}

char *getcwd(char *buf, size_t size) {
  static char *(*real_getcwd)(char *, size_t) = NULL;
  if (!real_getcwd) real_getcwd = dlsym(RTLD_NEXT, "getcwd");
  char *result = real_getcwd(buf, size);
  int saved = errno;
  fprintf(stderr, "TRACE getcwd(%zu)=%s errno=%d\n", size, result ? result : "NULL", saved);
  errno = saved;
  return result;
}

